function mouse_move_c40b7f435fa225e9c27d428821ebd8336b5f47af653c8b3eefb8452aab89768b28980d96bc1944d05e3dbf79e0f4994499dd6cb7b28ff49e71ccf61b12c3e737(evt) {
    if (evt.buttons > 0) {
          var root = document.getElementById('c40b7f435fa225e9c27d428821ebd8336b5f47af653c8b3eefb8452aab89768b28980d96bc1944d05e3dbf79e0f4994499dd6cb7b28ff49e71ccf61b12c3e737');
          root.pauseAnimations();
          var new_time = 3 * evt.layerX / evt.target.getBBox().width;
          root.setCurrentTime(new_time);
    }
}
function on_click_c40b7f435fa225e9c27d428821ebd8336b5f47af653c8b3eefb8452aab89768b28980d96bc1944d05e3dbf79e0f4994499dd6cb7b28ff49e71ccf61b12c3e737(evt) {
